function cards(items){return `<div class="metricgrid">${items.map(([title,value,detail])=>`<div class="metric"><span>${esc(title)}</span><b>${value}</b><span>${esc(detail??'')}</span></div>`).join('')}</div>`;}
function bar(values,names){const colors=g.S17Teach.rockColors;return `<div class="stack" role="img" aria-label="${esc(names.join('、'))}">${values.map((v,i)=>`<span style="width:${(v??0)*100}%;background:${colors[i%colors.length]}" title="${esc(names[i])} ${pct(v)}">${v>.08?pct(v):''}</span>`).join('')}</div><p class="fine">${names.map((n,i)=>`${esc(n)} ${pct(values[i])}`).join(' · ')}</p>`;}
function source(id,version,type,content){return{sourceRecordId:id,sourceVersion:version,sourceType:type,content};}
function claim(id,statement,sourceRecordId,sourceVersion,selector,extra={}){return{claimId:id,revision:sourceVersion,kind:'model_inference',statement,sourceRefs:[{sourceRecordId,sourceVersion,selector}],reviewStatus:'unreviewed',traceabilityStatus:'linked',supportStatus:'unchecked',reviewHistory:[],...extra};}
function envelope(caseId,version,run,content){return{schemaVersion:'1.0',caseId,caseVersion:version,runId:run.runId,datasetId:'s17-synthetic-v1',wellId:'DEMO-017',dataNature:'synthetic_teaching',runConfig:{seed:run.seed??17,dataVersion:run.dataVersion??'s17-synthetic-v1',splitDescription:run.split??'independent grouped training / validation / test',method:run.method,parameters:run.config,inputRevision:run.revision},...content};}
function session(id,version,lesson){const s={id,version,status:'not_run',revision:1,count:0,run:null,reviews:[],selected:0,step:0};
s.set=(status,message)=>{s.status=status;g.S17Visual?.state(status);$('status').className='status '+status;$('status').textContent=message;$('export').disabled=status!=='ready';$('run').disabled=status==='running';if($('review'))$('review').disabled=status!=='ready';if($('metrics-panel'))$('metrics-panel').hidden=status!=='ready'||!$('show-truth')?.checked;};
s.invalidate=()=>{s.revision++;s.reviews.forEach(r=>{if(r.reviewStatus==='confirmed'){r.reviewStatus='needs_review';r.traceabilityStatus='stale';r.supportStatus='unchecked';}});s.set(s.run?'stale':'not_run',s.run?'输入已变更；下方是旧结果，须重算。当前人工确认失效，导出已禁用。':'请运行计算。');};
s.finish=run=>{s.reviews.forEach(r=>{if(r.reviewStatus==='confirmed'){r.reviewStatus='needs_review';r.traceabilityStatus='stale';r.supportStatus='unchecked';}});s.run={...run,revision:s.revision,runId:`${id}-r${++s.count}-v${s.revision}`};s.set('ready','计算完成 · '+(run.dataNature==='mixed_teaching_and_public'?'教学文本与明示公开来源':'教学合成数据')+' · 当前结果已更新。');};
s.review=(label,note)=>{if(s.status!=='ready')throw Error('须先运行当前输入');if(!note.trim())throw Error('请填写复核依据');s.reviews.push({runId:s.run.runId,index:s.selected,label,note,sourceVersion:s.revision,reviewStatus:'confirmed',traceabilityStatus:'linked',supportStatus:'human_verified'});};
s.assertReady=()=>{if(s.status!=='ready')throw Error('当前结果待重算，不能导出');};
const showTab=t=>{for(const n of ['background','workflow','lab'])$(n).hidden=n!==t;document.querySelectorAll('nav [data-tab]').forEach(b=>(b.classList.toggle('active',b.dataset.tab===t),b.setAttribute('aria-pressed',String(b.dataset.tab===t))));};
$('background-content').innerHTML=lesson.background.map((b,i)=>`<article class="panel"><h2>图 B${i+1}｜${esc(b.title)}</h2><figure>${b.svg}<figcaption>${esc(b.caption)}</figcaption></figure></article>`).join('');
function step(){const a=lesson.steps[s.step];$('stepnav').innerHTML=lesson.steps.map((v,i)=>`<button data-step="${i}" class="${s.step===i?'active':''}">${i+1} ${esc(v.title)}</button>`).join('');$('step-content').innerHTML=`<article class="panel"><h2>图 S${s.step+1}｜${esc(a.title)}</h2>${a.svg}<div class="flowfacts"><div><b>输入</b>${esc(a.input)}</div><div><b>动作</b>${esc(a.action)}</div><div><b>输出</b>${esc(a.output)}</div></div><p class="fine">陷阱：${esc(a.trap)}</p></article><article class="panel"><h3>这一步的实际产物</h3><p>${s.run?esc(s.run.runId)+' · '+s.status:'尚未运行'}</p><div class="scroll">${s.run?.stepData?.[s.step]??'点击“运行计算”后显示实际中间结果。'}</div></article>`;}
s.stepRender=()=>{step();g.S17TeachingView?.magnify($('step-content'));};document.addEventListener('click',e=>{const b=e.target.closest('[data-tab],[data-step]');if(!b)return;if(b.dataset.tab)showTab(b.dataset.tab);if(b.dataset.step!=null){s.step=Number(b.dataset.step);s.stepRender();}});step();
g.S17TeachingView?.init(id==='s17-cuttings-lithology'?'m1':id==='s17-fluorescence-review'?'m3':id==='s17-drilltime-boundaries'?'m4':'m5',showTab);s.stepRender();
g.S17Inspect={snapshot:()=>({id:s.id,status:s.status,revision:s.revision,selected:s.selected,run:s.run?{runId:s.run.runId,config:s.run.config,metrics:s.run.metrics,method:s.run.method,summary:s.run.summary,counts:s.run.counts,stepCount:s.run.stepData?.length}:null,reviews:s.reviews}),evidence:()=>{s.assertReady();return s.exportEvidence();}};
return s;}
g.S17UI={$,esc,fmt,pct,table,canvas,readCanvas,download,matrix,cards,bar,source,claim,envelope,session};
